import axios from 'axios';

const BASE = 'http://localhost:8085/api';
const API_CARS = BASE + '/cars';
const API_RENTALS = BASE + '/rentals';
const API_CUSTOMERS = BASE + '/customers';
const API_PAYMENTS = BASE + '/payments';
const API_BRANCHES = BASE + '/branches';
const API_AUTH = BASE + '/auth';

const api = axios.create({
    baseURL: BASE
});

api.interceptors.request.use(function(config) {

    var token = localStorage.getItem('authToken');

    if (token) {
        config.headers.Authorization = 'Bearer ' + token;
    }

    return config;

});

api.interceptors.response.use(
    function(response) {
        return response;
    },
    function(error) {

        if (error.response && error.response.status === 401) {

            var url = error.config.url;

            if (url !== '/auth/login') {

                localStorage.removeItem('authToken');
                localStorage.removeItem('adminUser');
                window.location.reload();

            }

        }

        return Promise.reject(error);

    }
);

var apiFunctions = {

    login: function(data) {
        return api.post('/auth/login', data);
    },

    register: function(data) {
        return api.post('/auth/register', data);
    },

    logout: function() {
        return api.post('/auth/logout');
    },

    validateToken: function() {
        return api.get('/auth/validate');
    },

    findAllCars: function() {
        return api.get('/cars');
    },

    findCarById: function(id) {
        return api.get('/cars/' + id);
    },

    saveCar: function(item) {
        return api.post('/cars', item);
    },

    updateCar: function(id, item) {
        return api.put('/cars/' + id, item);
    },

    deleteCar: function(id) {
        return api.delete('/cars/' + id);
    },

    rentCar: function(data) {
        return api.post('/rentals', data);
    },

    findAllRentals: function() {
        return api.get('/rentals');
    },

    findRentalById: function(id) {
        return api.get('/rentals/' + id);
    },

    updateRental: function(id, item) {
        return api.put('/rentals/' + id, item);
    },

    deleteRental: function(id) {
        return api.delete('/rentals/' + id);
    },

    findAllCustomers: function() {
        return api.get('/customers');
    },

    findCustomerById: function(id) {
        return api.get('/customers/' + id);
    },

    saveCustomer: function(item) {
        return api.post('/customers', item);
    },

    updateCustomer: function(id, item) {
        return api.put('/customers/' + id, item);
    },

    deleteCustomer: function(id) {
        return api.delete('/customers/' + id);
    },

    findAllPayments: function() {
        return api.get('/payments');
    },

    findPaymentById: function(id) {
        return api.get('/payments/' + id);
    },

    savePayment: function(item) {
        return api.post('/payments', item);
    },

    updatePayment: function(id, item) {
        return api.put('/payments/' + id, item);
    },

    deletePayment: function(id) {
        return api.delete('/payments/' + id);
    },

    findAllBranches: function() {
        return api.get('/branches');
    },

    findBranchById: function(id) {
        return api.get('/branches/' + id);
    },

    saveBranch: function(item) {
        return api.post('/branches', item);
    },

    updateBranch: function(id, item) {
        return api.put('/branches/' + id, item);
    },

    deleteBranch: function(id) {
        return api.delete('/branches/' + id);
    }

};

export default apiFunctions;
